import { useProxyWatch } from "@fanfanlo";
import { user } from "./User";
import { useEffect, useState } from "react";

export function useUserName(){
    
    const [token] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
    const [globalInfo] = useProxyWatch(user, 'data.sessionData.global_user_info', user.data.sessionData.global_user_info)
    
    const [name, setName] = useState(user.userName);

    useEffect(()=>{
        setTimeout(() => {
            setName(user.userName)
        }, 100);
    }, [globalInfo])
    if(!token){
        return ['']
    }
    return [name]
    
}