import { publicRuntimeConfig, Region, useTranslation } from "@fanfanlo";
import { useRouter } from "next/router";
import { useProxyWatch } from "@fanfanlo";
import { user } from "@app/model";
import toast from "react-hot-toast";
import { Box, Button } from "@mui/material";
import Link from "next/link";
import { ButtonConfirm } from "@fanfanlo";
import { LoginButtonBox } from "@src/components/Login/GoogleLoginButton";
import { isRealInAndroid } from "@droid/android";

interface SignUpInButtonProps{
    back?:string;
}

export function SignUpInButton({back}:SignUpInButtonProps){
    // apps\homepage\src\components\page\sign-up-in\components\sign-up-in-button\SignUpIn.i18n.json
    const { t } = useTranslation('homepage/components/page/sign-up-in/components/sign-up-in-button/content');
    const router = useRouter();
    const [token] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
    const [userInitialized] = useProxyWatch(user, 'data.userInitialized', user.data.userInitialized);
    function onSignoutClick(){
        user.signout();
        toast(t('SignUpIn.signoutOk'), { duration: 5000 })
    }
    if(!userInitialized){
        return (
            <>
            {t('SignUpIn.loadingData')}
            </>
        )
    }
    if(token){
        return (<></>)
        return(
            <Box>
                <Box>
                    <span>
                        {user.userName}
                    </span>
                </Box>
                <Box>
                <span>
                    <ButtonConfirm
                      title={t('SignUpIn.confirmTitle')}
                      content={t('SignUpIn.confirmContent')}
                      onConfirm={onSignoutClick}
                      data-testid="SignUpInButton__signOutConfirmDialog__01aryz6s610p4z0skjq69x5prw"
                      data-test-comment="退出登录确认对话框，用户点击退出按钮后弹出，需要用户确认才能执行退出"
                    >
                      <Button
                        data-testid="SignUpInButton__signOutButton__01aryz6s610p4z0skjq69x5prx"
                        data-test-comment="退出登录按钮，点击后弹出确认对话框，确认后执行退出操作"
                      >
                        {t('SignUpIn.signOut')}
                      </Button>
                    </ButtonConfirm>
                </span>
                </Box>
            </Box>
        )
    }
    return (
        <>
            
                        {(publicRuntimeConfig.region == Region.CN || !isRealInAndroid)&& <>
            <span>
                <Link
                  href={`/sign-up-in?back=${back}`}
                  data-testid="SignUpInButton__signUpInLink__01aryz6s610p4z0skjq69x5prv"
                  data-test-comment="登录/注册链接，点击后导航到登录/注册页面，支持返回链接参数"
                >
                  {t('SignUpIn.signUpIn')}
                </Link>
            </span>
        </>}
                        {publicRuntimeConfig.region == Region.GLOBAL && isRealInAndroid && <LoginButtonBox />}
        </>
    )
    return (
        <>
            <span>
                <Link href={`/sign-up-in?back=${back}`}>{t('SignUpIn.signUpIn')}</Link>
            </span>
        </>
    )
}
